glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
layout(std140) uniform CCLocal {
  highp mat4 cc_matWorld;
  highp mat4 cc_matWorldIT;
  highp vec4 cc_lightingMapUVParam;
  highp vec4 cc_localShadowBias;
  highp vec4 cc_reflectionProbeData1;
  highp vec4 cc_reflectionProbeData2;
  highp vec4 cc_reflectionProbeBlendData1;
  highp vec4 cc_reflectionProbeBlendData2;
};
in vec3 a_position;
out vec2 fieldUV;
out float throughSlit;
out vec3 litAir;
out vec4 airLayer;
out vec4 fanSpace;
layout(std140) uniform SpillParameters {
  vec4 fieldRect;
  vec4 fieldFocus;
  vec4 sourceShape;
  vec4 exposure;
  vec4 slitBounds;
  vec4 airPulse;
  vec4 sourceStrip[16];
  vec4 exitStrip[16];
};
float topFanRadiance(vec2 d, vec4 slit, vec4 lobe, float binWidth, float airDepth) {
  if (d.y <= 0.) return 0.;
  float spread = 4.5+lobe.y*d.y;
  float invWidth = inversesqrt(spread*spread+binWidth*binWidth/12.);
  float q = (d.x-lobe.x*d.y)*invWidth;
  float travel = d.y/(156.+124.*airDepth);
  float density = smoothstep(0.,5.,d.y)*exp(-travel*(.72+.49*travel));
  return .399*slit.z*lobe.z*invWidth*exp(-.5*q*q)*density
         / (2.65+.28*slit.w+.014*d.y);
}
vec4 vert () {
  vec2 t = a_position.xy;
  vec2 lo = fieldFocus.xy;
  vec2 hi = fieldFocus.zw;
  fieldUV = lo * clamp(t/.17,0.,1.) + (hi-lo)*clamp((t-.17)/.66,0.,1.)
          + (1.-hi)*clamp((t-.83)/.17,0.,1.);
  vec2 p = fieldRect.xy + fieldUV * fieldRect.zw;
  fanSpace = vec4(p.x-slitBounds.x, p.y-sourceShape.w, slitBounds.y-slitBounds.x, cc_time.x);
  throughSlit = 0.;
  float airDepth = sqrt(exposure.y);
  float front = exposure.w;
  for (int i = 0; i < 16; i++) {
    vec4 s = sourceStrip[i];
    if (s.z <= 0.) continue;
    vec2 offset = p-s.xy;
    float plume = topFanRadiance(offset,s,exitStrip[i],sourceShape.x,airDepth);
    float r = length(offset);
    float spill = .022*s.z*exp(-r/13.)/(26.+r);
    if (front > .5) {
      float cleared = smoothstep(.25*s.w,.58*s.w+4.,offset.y);
      plume *= .66*cleared*exp(-r/94.);
      spill *= .30*cleared;
    }
    throughSlit += plume+spill;
  }
  airLayer = vec4(front,airPulse.yzw);
  float onset = smoothstep(.006,.24,airDepth)*(.76+.37*airDepth);
  litAir = vec3(exposure.z*onset*mix(.62,1.,sourceShape.z),airPulse.x,sourceShape.z);
  return cc_matViewProj * cc_matWorld * vec4(p, 0., 1.);
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
in vec2 fieldUV;
in float throughSlit;
in vec3 litAir;
in vec4 airLayer;
in vec4 fanSpace;
float densityHash(vec2 cell) {
  vec3 p = fract(cell.xyx*vec3(.1031,.1030,.0973));
  p += dot(p,p.yzx+33.33);
  return fract((p.x+p.y)*p.z);
}
float airDensity(vec2 p) {
  vec2 cell = floor(p);
  vec2 f = fract(p);
  vec2 u = f*f*(3.-2.*f);
  return mix(mix(densityHash(cell),densityHash(cell+vec2(1.,0.)),u.x),
             mix(densityHash(cell+vec2(0.,1.)),densityHash(cell+vec2(1.)),u.x),u.y);
}
float apertureFootprint(float h) {
  float width = 4.+.23*h;
  float outside = max(max(-fanSpace.x,fanSpace.x-fanSpace.z),0.);
  return exp(-2.6*outside*outside/(width*width));
}
vec3 liningLight(float h, float flux, float motion, float pulse, float front) {
  float span = fanSpace.z, u = fanSpace.x;
  float t = fanSpace.w;
  float progress = smoothstep(8.,260.,span);
  float foot = u-h*(.052+.059*sin(u*.020));
  float drift = 3.*sin(h*.012-t*.77+u*.023)*smoothstep(0.,100.,h);
  float facet = airDensity(vec2((foot+drift)*.028+5.3,h*.007-t*.23));
  float fleck = airDensity(vec2((foot+9.*facet)*.054+2.9,h*.012-t*.45));
  float near = exp(-h/65.);
  float face = smoothstep(.20,.75,.68*facet+.32*fleck);
  float hot = .5+.5*cos(foot*.086+.91*sin(foot*.037+.6)+facet*.47);
  hot = hot*hot*(.45+.55*face);
  float reach = 41.+30.*progress+27.*motion+19.*face+99.*pulse;
  float height = h/(reach*mix(.84,1.,litAir.z));
  float veil = exp(-height*height);
  float glow = exp(-h/(22.+29.*progress));
  vec3 body = mix(vec3(1.14,1.31,1.39),vec3(2.36,1.13,.35),litAir.z);
  vec3 pearl = mix(vec3(1.63,1.64,1.51),vec3(2.20,1.70,.92),litAir.z);
  float local = .28+.72*face;
  if (front > .5) {
    vec3 reflected = body*(.32+.65*hot)*glow +
                     pearl*(.22+.82*hot)*near*(.77+.36*motion);
    return flux*(1.12+.14*progress)*reflected;
  }
  vec3 fill = body*((.59+.30*face)*glow+(.29+.24*motion)*veil);
  vec3 reflected = mix(body,pearl,.38+.40*near)*veil*
                   (.24+.51*motion+.29*pulse)*local*(.45+.93*hot);
  return flux*(1.39+.24*progress+.17*motion)*(fill+reflected);
}
vec4 frag () {
  vec2 border = min(fieldUV, 1.0 - fieldUV);
  float feather = smoothstep(0.0, .105, min(border.x, border.y));
  vec3 light = vec3(0.);
  if (litAir.x > 0.) {
    float h = max(0.,fanSpace.y);
    float motion = mix(airLayer.y,airLayer.z,smoothstep(6.,62.,h));
    motion = mix(motion,airLayer.w,smoothstep(62.,153.,h));
    float elapsed = litAir.y;
    float pulse = 0.;
    if (elapsed >= 0.) {
      float arrival = (elapsed-.054-h/1210.)/(.065+h*.00022);
      pulse = exp(-arrival*arrival);
      motion = max(motion,pulse);
    }
    float fed = elapsed < 0. ? 1. : 1.-smoothstep(.04+h/870.,.18+h/870.,elapsed);
    float flux = apertureFootprint(h)*throughSlit/(.43+throughSlit);
    if (airLayer.x < .5) {
      vec3 sheets = liningLight(h,flux,motion,pulse,0.);
      vec3 crestColor = mix(vec3(1.56,1.73,1.84),vec3(3.13,2.29,1.11),litAir.z);
      vec3 crest = pulse*flux*exp(-h/211.)*crestColor;
      light += litAir.x*(sheets*fed*(1.+pulse*.97)+crest);
    } else {
      light += litAir.x*fed*liningLight(h,flux,motion,pulse,1.)*(.87+.36*pulse);
    }
  }
  return vec4((1.0 - exp(-light)) * feather, 0.);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

